select id, event_type, event_time, sum(duration_sec) over (order by cast(event_time as bigint) range between 2592000 preceding and current row) as duration_sec_sum_30d, dense_rank() over (partition by session_id order by duration_sec desc) as duration_sec_dense_rank, lead(duration_sec, 1) over (partition by event_type order by event_time, id) as next_duration_sec from web_events where session_id = 35
